export default async function next(
  { nocoUrl, baseId, songsTable, playlistsTable, userId, acknowledge, confirmedPlaylistId },
  ctx,
) {
  if (!/^https:\/\//.test(nocoUrl) || nocoUrl.includes("YOUR_"))
    throw Error("Configure public HTTPS NocoDB URL");
  if ([baseId, songsTable, playlistsTable, userId].some((x) => !x || x.includes("YOUR_")))
    throw Error("Configure NocoDB base and tables and Spotify user ID");
  let s = await ctx.state.get("monthly-spotify");
  if (!s) {
    const d = new Date(),
      name =
        d.toLocaleString("en-US", { month: "long", timeZone: "UTC" }) +
        " '" +
        String(d.getUTCFullYear()).slice(-2);
    s = {
      phase: "likes",
      month: name,
      offset: 0,
      page: 1,
      songs: [],
      playlists: [],
      dbPlaylists: [],
      existingTracks: [],
      likes: [],
      index: 0,
      pending: null,
      playlist: null,
    };
    await ctx.state.set("monthly-spotify", s);
  }
  if (s.pending) {
    if (acknowledge !== s.pending) throw Error("Inspect external write " + s.pending);
    if (s.pending === "spotify-playlist") {
      if (!confirmedPlaylistId) throw Error("Set confirmed playlist ID after inspecting Spotify");
      s.playlist = {
        id: confirmedPlaylistId,
        uri: "spotify:playlist:" + confirmedPlaylistId,
        name: s.month,
        description: "Monthly playlist",
      };
      s.phase = "db-playlists";
      s.page = 1;
    } else if (s.pending === "db-song") {
      const item = s.likes[s.index];
      s.songs.push({ uri: item.track.uri, added_at: item.added_at, playlistName: s.month });
      s.index++;
    } else if (s.pending === "db-playlist") {
      s.phase = "tracks";
      s.offset = 0;
    } else if (s.pending === "spotify-track") s.index++;
    s.pending = null;
    await ctx.state.set("monthly-spotify", s);
  }
  for (;;) {
    let action = s.phase,
      tableId = songsTable,
      records = [{ fields: { uri: "placeholder" } }],
      uris = ["spotify:track:placeholder"],
      playlistId = s.playlist?.id ?? "placeholder",
      name = s.month,
      offset = s.offset,
      page = s.page;
    if (action === "write-songs") {
      while (s.index < s.likes.length && s.songs.some((r) => r.uri === s.likes[s.index].track?.uri))
        s.index++;
      if (s.index >= s.likes.length) {
        s.phase = "playlists";
        s.index = 0;
        s.offset = 0;
        await ctx.state.set("monthly-spotify", s);
        continue;
      }
      const item = s.likes[s.index];
      if (!item.track?.uri) throw Error("Liked track has no Spotify URI");
      records = [
        { fields: { uri: item.track.uri, added_at: item.added_at, playlistName: s.month } },
      ];
      s.pending = "db-song";
      await ctx.state.set("monthly-spotify", s);
    }
    if (action === "select-playlist") {
      const matches = s.playlists.filter((p) => p.name === s.month);
      if (matches.length > 1)
        throw Error("Multiple monthly playlists; select one before continuing");
      if (matches.length) {
        s.playlist = matches[0];
        s.phase = "db-playlists";
        s.page = 1;
        await ctx.state.set("monthly-spotify", s);
        continue;
      }
      s.phase = "create-playlist";
      continue;
    }
    if (action === "create-playlist") {
      s.pending = "spotify-playlist";
      await ctx.state.set("monthly-spotify", s);
    }
    if (action === "db-playlists") tableId = playlistsTable;
    if (action === "select-db-playlist") {
      let matches = s.dbPlaylists.filter((r) => r.name === s.month);
      if (matches.length > 1) throw Error("Multiple monthly NocoDB playlist rows");
      if (matches.length && matches[0].uri !== s.playlist.uri)
        throw Error("Monthly playlist differs between NocoDB and Spotify");
      if (matches.length) {
        s.phase = "tracks";
        s.offset = 0;
        await ctx.state.set("monthly-spotify", s);
        continue;
      }
      s.phase = "create-db-playlist";
      continue;
    }
    if (action === "create-db-playlist") {
      tableId = playlistsTable;
      records = [
        {
          fields: { uri: s.playlist.uri, name: s.month, description: s.playlist.description ?? "" },
        },
      ];
      s.pending = "db-playlist";
      await ctx.state.set("monthly-spotify", s);
    }
    if (action === "add-tracks") {
      let desired = s.songs.filter((x) => x.playlistName === s.month);
      while (s.index < desired.length && s.existingTracks.includes(desired[s.index].uri)) s.index++;
      if (s.index >= desired.length) {
        s.phase = "done";
        continue;
      }
      uris = [desired[s.index].uri];
      if (!uris[0]) throw Error("Monthly NocoDB record has no track URI");
      s.pending = "spotify-track";
      await ctx.state.set("monthly-spotify", s);
    }
    if (action === "done") {
      await ctx.state.set("monthly-spotify", null);
      return {
        action,
        baseId,
        tableId,
        page: 1,
        offset: 0,
        playlistId: "placeholder",
        userId,
        records,
        uris,
        name,
        url: nocoUrl,
      };
    }
    return {
      action,
      baseId,
      tableId,
      page,
      offset,
      playlistId,
      userId,
      records,
      uris,
      name,
      url:
        nocoUrl.replace(/\/$/, "") +
        "/api/v3/data/" +
        encodeURIComponent(baseId) +
        "/" +
        encodeURIComponent(tableId) +
        "/records" +
        (action === "songs" || action === "db-playlists" ? "?page=" + page + "&pageSize=100" : ""),
    };
  }
}

