async function result({ kind, data }, ctx) {
  const s = await ctx.state.get("monthly-spotify");
  if (!s) throw Error("Missing monthly sync state");
  if (kind === "likes") {
    s.likes = data.items;
    s.phase = "songs";
    s.page = 1;
  } else if (kind === "songs" || kind === "db-playlists") {
    if (!Array.isArray(data.records)) throw Error("Invalid NocoDB records");
    s[kind === "songs" ? "songs" : "dbPlaylists"].push(
      ...data.records.map((r) => ({ ...r.id_fields, ...r.fields })),
    );
    if (data.next) {
      s.page++;
    } else {
      if (kind === "songs") {
        s.phase = "write-songs";
        s.index = 0;
      } else {
        s.phase = "select-db-playlist";
      }
      s.page = 1;
    }
  } else if (kind === "write-songs") {
    s.songs.push({
      uri: s.likes[s.index].track.uri,
      added_at: s.likes[s.index].added_at,
      playlistName: s.month,
    });
    s.index++;
    s.pending = null;
  } else if (kind === "playlists") {
    s.playlists.push(...data.items);
    if (data.next) {
      if (!data.items.length) throw Error("Empty Spotify page");
      s.offset += data.items.length;
    } else {
      s.phase = "select-playlist";
      s.offset = 0;
    }
  } else if (kind === "create-playlist") {
    s.playlist = data;
    s.pending = null;
    s.phase = "db-playlists";
    s.page = 1;
  } else if (kind === "create-db-playlist") {
    s.pending = null;
    s.phase = "tracks";
    s.offset = 0;
  } else if (kind === "tracks") {
    s.existingTracks.push(...data.items.map((x) => x.track?.uri).filter(Boolean));
    if (data.next) {
      if (!data.items.length) throw Error("Empty Spotify track page");
      s.offset += data.items.length;
    } else {
      s.phase = "add-tracks";
      s.index = 0;
    }
  } else if (kind === "add-tracks") {
    s.index++;
    s.pending = null;
  } else throw Error("Unexpected result");
  await ctx.state.set("monthly-spotify", s);
  return { ok: true };
}

export default async function execute({ output }, ctx) {
  return result({ kind: "likes", data: output }, ctx);
}

